foreach ( $t126 as $id => list( $t, $D, $s1, $sb, $pn, $dn, $L, $H, $m ) ) {
	$mpa = rtrim( rtrim( number_format( (float) $pn / 10, 3, '.', '' ), '0' ), '.' );
	$pnl = $fmt( $pn );
	$plan[ $id ] = [
		'set' => [
			'outer_diameter' => (string) $D, 'wall_thickness' => $s1,
			'outer_d_branch' => (string) $D, 'wall_branch' => $s1, 'wall_body' => $sb,
