			'execution' => $t, 'gost_designation' => "{$D}х{$s1}-PN{$pnl}", 'equal_pass' => 'да',
			'length' => (string) $L, 'length_mm' => (string) $L, 'height_mm' => (string) $H, 'height_h' => (string) $H,
			'product_type' => 'ТР',
		],
		'unset'   => [],
		'title'   => "Тройник равнопроходный {$D}х{$s1}-PN{$pnl} {$t} СТО 95 126-2013",
		'content' => "Тройник сварной равнопроходный по СТО 95 126-2013, типоразмер {$t}. DN {$dn}, PN {$pnl}. "
			. "Присоединяемые трубы {$D}×" . $fmt( $s1 ) . " мм, толщина стенки корпуса " . $fmt( $sb ) . " мм. "
			. "L = {$L} мм, H = {$H} мм. Масса " . $fmt( $m ) . ' кг (справочная).',
		'weight'  => $m,
		'note'    => 'СТО 95 126',
	];
}

