$pn425 = static function ( int $n ): array {
	if ( $n <= 25 ) return [ '0.25', '2,5' ];
	if ( $n <= 49 ) return [ '0.6', '6' ];
	if ( $n <= 69 ) return [ '1', '10' ];
	if ( $n <= 89 ) return [ '1.6', '16' ];
	return [ '2.5', '25' ];
};
$term = get_term_by( 'name', 'ОСТ 34-10-425-90', 'norm' );
foreach ( $term ? (array) get_objects_in_term( [ $term->term_id ], 'norm' ) : [] as $id ) {
	$id   = (int) $id;
	$d    = $dims_of( $id );
	$pipe = ( $d['outer_diameter'] ?? '' ) . 'х' . ( $d['wall_thickness'] ?? '' );
	$cand = [];
	if ( preg_match( '/DN(\d+)/u', get_the_title( $id ), $mm ) ) {
		$cand[] = (int) $mm[1];
	}
	$cand[] = (int) ( $d['execution'] ?? 0 );
	$n = 0;
	foreach ( $cand as $c ) {
		if ( isset( $t425[ (string) $c ] ) && $t425[ (string) $c ][1] === $pipe ) {
			$n = $c;
			break;
		}
	}
	if ( ! $n ) {
		WP_CLI::warning( "425: не сопоставлен {$id} " . get_the_title( $id ) . " ({$pipe})" );
		continue;
	}
	list( $dy, $tp, $Dfl, $D1, $Dn, $S, $L, $hole, $holes, $m ) = $t425[ (string) $n ];
	list( $mpa, $pnl ) = $pn425( $n );
	$nn = sprintf( '%02d', $n );
	$plan[ $id ] = [
		'set' => [
			'dn' => $dy, 'pn' => $mpa, 'execution' => $nn, 'gost_designation' => $tp,
			'bolt_circle_d' => $D1, 'stud_count' => $holes, 'length' => $L, 'length_mm' => $L,
			'product_type' => 'ФП',
		],
		'unset'   => array_values( array_intersect( [ 'outer_d_branch', 'dn_branch', 'wall_branch' ], array_keys( $d ) ) ),
		'title'   => "Фланец плоский {$tp} PN{$pnl} исп. {$nn} ОСТ 34-10-425-90",
		'content' => "Фланец плоский приварной с патрубком по ОСТ 34-10-425-90, обозначение {$nn}. DN {$dy}, Ру " . $fmt( $mpa ) . ' МПа. '
			. "Присоединяемая труба " . $fmt( $tp ) . " мм. D = {$Dfl} мм, D1 = {$D1} мм, патрубок {$Dn}×" . $fmt( $S ) . " мм, L = {$L} мм, "
			. "{$holes} отв. Ø{$hole} мм. Масса " . $fmt( $m ) . ' кг. Материал по стандарту — 08Х18Н10Т.',
		'weight'  => $m,
		'note'    => 'ОСТ 34-10-425',
	];
}

// ── Отчёт ──────────────────────────────────────────────────────────────────
foreach ( $plan as $id => $p ) {
	$old = $dims_of( $id );
	$chg = [];
	foreach ( $p['set'] as $k => $v ) {
		if ( (string) ( $old[ $k ] ?? '' ) !== (string) $v ) {
			$chg[] = "{$k} " . ( $old[ $k ] ?? '—' ) . "→{$v}";
		}
	}
	WP_CLI::log( sprintf( '%s %d «%s» → «%s»; вес %s→%s', $p['note'], $id, get_the_title( $id ), $p['title'], get_post_meta( $id, '_weight', true ) ?: '—', $p['weight'] ) );
	WP_CLI::log( '    ' . implode( ', ', $chg ) . ( $p['unset'] ? ' −' . implode( ' −', $p['unset'] ) : '' ) );
}
foreach ( $merge as $from => $to ) {
	WP_CLI::log( "склейка: {$from} «" . get_the_title( $from ) . "» → {$to}" );
}

if ( ! $apply ) {
	WP_CLI::log( 'Отчёт. Для правки: ... eval-file _rebuild_sto95126_ost425.php apply' );
	return;
}

// Слепок: посты (с вариациями), мета, связи — удаляемую карточку можно поднять целиком.
$ids = array_merge( array_keys( $plan ), array_keys( $merge ) );
foreach ( $ids as $id ) {
	$ids = array_merge( $ids, array_map( 'intval', (array) $wpdb->get_col( $wpdb->prepare( "SELECT ID FROM {$wpdb->posts} WHERE post_parent = %d AND post_type = 'product_variation'", $id ) ) ) );
}
$in   = implode( ',', array_unique( array_map( 'intval', $ids ) ) );
$snap = rtrim( (string) getenv( 'HOME' ), '/' ) . '/rebuild-95126-425-snapshot-' . gmdate( 'Ymd-His' ) . '.json';
file_put_contents( $snap, wp_json_encode( [
	'posts'     => $wpdb->get_results( "SELECT * FROM {$wpdb->posts} WHERE ID IN ({$in})", ARRAY_A ),
	'meta'      => $wpdb->get_results( "SELECT * FROM {$wpdb->postmeta} WHERE post_id IN ({$in})", ARRAY_A ),
	'terms'     => $wpdb->get_results( "SELECT * FROM {$wpdb->term_relationships} WHERE object_id IN ({$in})", ARRAY_A ),
	'redirects' => get_option( 'promen_dedup_redirects', [] ),
], JSON_UNESCAPED_UNICODE ) );
WP_CLI::log( 'Слепок: ' . $snap );

$done = 0;
foreach ( $plan as $id => $p ) {
	$d = $dims_of( $id );
	foreach ( $p['set'] as $k => $v ) {
		$d[ $k ] = $v;
	}
	foreach ( $p['unset'] as $k ) {
		unset( $d[ $k ] );
	}
	update_post_meta( $id, '_promen_dims', wp_json_encode( $d, JSON_UNESCAPED_UNICODE ) );
	update_post_meta( $id, '_promen_gost_designation', $p['set']['gost_designation'] );
	update_post_meta( $id, '_weight', $p['weight'] );

	$t_old = (string) get_post_field( 'post_title', $id );
	foreach ( (array) $wpdb->get_results( $wpdb->prepare( "SELECT ID, post_title FROM {$wpdb->posts} WHERE post_parent = %d AND post_type = 'product_variation'", $id ) ) as $v ) {
		if ( 0 === strpos( $v->post_title, $t_old ) ) {
			$wpdb->update( $wpdb->posts, [ 'post_title' => $p['title'] . substr( $v->post_title, strlen( $t_old ) ) ], [ 'ID' => (int) $v->ID ] );
			clean_post_cache( (int) $v->ID );
		}
	}
	// Прямой UPDATE: wp_update_post пересобрал бы слаг и дёрнул save_post у Woo.
	$wpdb->update( $wpdb->posts, [ 'post_title' => $p['title'], 'post_content' => $p['content'] ], [ 'ID' => $id ] );
	clean_post_cache( $id );
	if ( function_exists( 'promen_catalog_upsert' ) ) {
		promen_catalog_upsert( $id, false );
	}
	$done++;
}

$redirects = get_option( 'promen_dedup_redirects', [] );
if ( ! is_array( $redirects ) ) {
	$redirects = [];
}
foreach ( $merge as $from => $to ) {
	$slug = (string) get_post_field( 'post_name', $from );
	$product = wc_get_product( $from );
	if ( $product ) {
		foreach ( $product->get_children() as $vid ) {
			wp_delete_post( (int) $vid, true );
		}
		$product->delete( true );
	}
	if ( function_exists( 'promen_catalog_delete' ) ) {
		promen_catalog_delete( $from );
	}
	foreach ( $redirects as $k => $v ) {
		if ( (int) $v === $from ) {
			$redirects[ $k ] = $to;
		}
	}
	if ( '' !== $slug ) {
		$redirects[ $slug ] = $to;
	}
	WP_CLI::log( "  склеено: {$from} ({$slug}) → {$to}" );
}
update_option( 'promen_dedup_redirects', $redirects, false );

wp_cache_flush();
if ( function_exists( 'promen_filters_cache_bump' ) ) {
	promen_filters_cache_bump();
}
delete_transient( 'promen_series_sitemap' );
WP_CLI::success( "Пересобрано карточек: {$done}, склеено: " . count( $merge ) . '. Дальше: wp promen cache-purge.' );
